package br.com.marquesautodetail.api.agendamento;
import br.com.marquesautodetail.api.empresa.Empresa;import br.com.marquesautodetail.api.servico.Servico;import br.com.marquesautodetail.api.usuario.Usuario;import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="agendamentos") public class Agendamento{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private LocalDate data; private LocalTime hora; @Enumerated(EnumType.STRING) private StatusAgendamento status=StatusAgendamento.PENDENTE; @Column(length=1000) private String observacao; @ManyToOne @JoinColumn(name="cliente_id") private Usuario cliente; @ManyToOne @JoinColumn(name="empresa_id") private Empresa empresa; @ManyToOne @JoinColumn(name="servico_id") private Servico servico; private LocalDateTime criadoEm=LocalDateTime.now(); public Long getId(){return id;} public void setId(Long id){this.id=id;} public LocalDate getData(){return data;} public void setData(LocalDate data){this.data=data;} public LocalTime getHora(){return hora;} public void setHora(LocalTime hora){this.hora=hora;} public StatusAgendamento getStatus(){return status;} public void setStatus(StatusAgendamento status){this.status=status;} public String getObservacao(){return observacao;} public void setObservacao(String observacao){this.observacao=observacao;} public Usuario getCliente(){return cliente;} public void setCliente(Usuario cliente){this.cliente=cliente;} public Empresa getEmpresa(){return empresa;} public void setEmpresa(Empresa empresa){this.empresa=empresa;} public Servico getServico(){return servico;} public void setServico(Servico servico){this.servico=servico;} public LocalDateTime getCriadoEm(){return criadoEm;} public void setCriadoEm(LocalDateTime criadoEm){this.criadoEm=criadoEm;} }
